"""Chapter 9 - Offences by or relating to public servants (ss 161-171)."""
from lib import *

HEADER = """-- Singapore Penal Code 1871 - Chapter 9, Offences by or relating to public
-- servants (ss 161-171). Part of the state-public group (Chapters 6-10).
--
-- Source: Penal Code 1871, 2020 Revised Edition, SSO current version as at
-- 09 Sep 2026 (inputs/PC1871.txt). Each section's text is quoted above its rules.
--
-- GENERATED by notes/state-public-gen/build.py from the hand-written ladders in
-- notes/state-public-gen/part_servants.py; edit there and rebuild.
--
-- ss 161-165 are the Code's own gratification offences. In practice most
-- corruption is charged under the Prevention of Corruption Act 1960, which is
-- not in this job's inputs; nothing here reads it."""

TAKES = ["accepts", "obtains", "agrees to accept", "attempts to obtain"]
TAKE_FIELDS = [
    ("accepts", "B", "Did the taker accept it?"),
    ("obtains", "B", "Did the taker obtain it?"),
    ("agrees to accept", "B", "Did the taker agree to accept it?"),
    ("attempts to obtain", "B", "Did the taker attempt to obtain it?"),
]
TAKE_LADDER = """(    f's accepts
         OR  f's obtains
         OR  f's `agrees to accept`
         OR  f's `attempts to obtain` )"""
TAKE_EXPR = "f's accepts OR f's obtains OR f's `agrees to accept` OR f's `attempts to obtain`"


def take_verb():
    return """(`joined with` " or " (concat (LIST (`included if` (f's accepts) "accept"), (`included if` (f's obtains) "obtain"), (`included if` (f's `agrees to accept`) "agree to accept"), (`included if` (f's `attempts to obtain`) "attempt to obtain"))))"""


def module():
    out = [HEADER, "", "IMPORT prelude", "IMPORT `pc-domain`", "IMPORT `pc-general`",
           "IMPORT `pc-state-public-common`", "",
           "§ `Chapter 9 - Offences by or relating to public servants`", ""]
    A = out.append

    # 161
    OG = "Official Gratification Facts"
    A(section("161", "Public servant taking a gratification, other than legal remuneration, in respect of an official act"))
    A("")
    A(facts(OG, "Penal Code 1871 s 161 and its Explanations", [
        PS,
        ("expecting to be a public servant", "B", "Was the accused expecting to be a public servant? (Explanation: a person NOT expecting to be in office who deceives others into believing they soon will be may be guilty of cheating, but not of this offence.)"),
    ] + [(n, t, d.replace("the taker", "the accused")) for n, t, d in TAKE_FIELDS] + [
        ("any gratification whatever", "B", "Was what the accused accepted or obtained (or agreed or attempted to) a gratification? (Explanation: not restricted to money or things estimable in money.)"),
        ("other than legal remuneration", "B", "Was it something other than legal remuneration? (Explanation: legal remuneration includes all remuneration the public servant is permitted by law to accept, not only what can be lawfully demanded.)"),
        ("as a motive or reward", "B", "Was it a motive or reward? (Explanation: a motive for doing what the accused does not intend to do, or a reward for what the accused has not done, counts.)"),
        ("for doing or forbearing to do any official act", "B", "... for doing or forbearing to do an official act?"),
        ("for showing or forbearing to show, in the exercise of his official functions, favour or disfavour to any person", "B", "... for showing or forbearing to show favour or disfavour to anyone in the exercise of the accused's official functions?"),
        ("for rendering or attempting to render any service or disservice to any person, with the Government, or with any Member of Parliament or the Cabinet, or with any public servant, as such", "B", "... for rendering or attempting to render any service or disservice to anyone with the Government, a Member of Parliament or the Cabinet, or a public servant as such?"),
        ("the giver", "P", "The person from whom the gratification was accepted or obtained, as the charge names them"),
        ("the gratification", "S", "The gratification, as it is to read in the charge - for example \"a sum of $5,000\""),
        ("the official act", "S", "What it was a motive or reward for, as it is to read in the charge - for example \"for deciding a cause in favour of the said Zainal bin Osman\""),
        TO_WIT,
    ]))
    A("")
    A(simple_pun("161", "3 years", 36))
    A("")
    A(rule("takes a gratification in respect of an official act", OG,
           "Whether a public servant (or one expecting to be) takes a gratification other than legal remuneration as a motive or reward for an official act, within section 161 of the Penal Code 1871",
           f"""        "Whoever, being"
    AND (    f's `public servant`
         OR  f's `expecting to be a public servant` )
    AND {TAKE_LADDER}
    AND "from any person, for himself or for any other person,"
    AND f's `any gratification whatever`
    AND f's `other than legal remuneration`
    AND f's `as a motive or reward`
    AND (    f's `for doing or forbearing to do any official act`
         OR  f's `for showing or forbearing to show, in the exercise of his official functions, favour or disfavour to any person`
         OR  f's `for rendering or attempting to render any service or disservice to any person, with the Government, or with any Member of Parliament or the Cabinet, or with any public servant, as such` )"""))
    A("")
    A(rule("offence under s 161", OG,
           "Whether the accused has committed an offence punishable under section 161 of the Penal Code 1871 (public servant taking a gratification in respect of an official act)",
           """        "Whoever"
    ... `takes a gratification in respect of an official act` f"""))
    A("")
    A(charge("161", "public servant taking a gratification, other than legal remuneration, in respect of an official act", "offence under s 161",
             """CONCAT "being a public servant, did """ + '", ' + take_verb() + """, " from ", `one person` (f's `the giver`), ", a gratification other than legal remuneration, namely ", f's `the gratification`, ", as a motive or reward ", f's `the official act`, `the to-wit clause` (f's `to wit`)""",
             [("f's `public servant` OR f's `expecting to be a public servant`", "being or expecting to be a public servant"),
              (TAKE_EXPR, "accepts or obtains, or agrees to accept or attempts to obtain"),
              ("f's `any gratification whatever`", "any gratification"),
              ("f's `other than legal remuneration`", "other than legal remuneration"),
              ("f's `as a motive or reward`", "as a motive or reward"),
              ("f's `for doing or forbearing to do any official act` OR f's `for showing or forbearing to show, in the exercise of his official functions, favour or disfavour to any person` OR f's `for rendering or attempting to render any service or disservice to any person, with the Government, or with any Member of Parliament or the Cabinet, or with any public servant, as such`", "for an official act, for favour or disfavour, or for service or disservice with the Government or a public servant"),
              ("`takes a gratification in respect of an official act` f", "the elements of section 161 taken together")],
             OG))
    A("")

    # 162, 163, 164
    GI = "Gratification to Influence Facts"
    A(section("162", "Taking a gratification in order, by corrupt or illegal means, to influence a public servant"))
    A("")
    A(facts(GI, "Penal Code 1871 ss 162, 163, 164", TAKE_FIELDS + [
        ("any gratification whatever", "B", "Was what the taker accepted or obtained a gratification (not restricted to money - s 161 Explanation)?"),
        ("as a motive or reward for inducing", "B", "Was it a motive or reward for inducing a public servant to act as below?"),
        ("by corrupt or illegal means", "B", "s 162: ... by corrupt or illegal means (s 43)?"),
        ("by the exercise of personal influence", "B", "s 163: ... by the exercise of personal influence? (s 163 illustration: an advocate arguing a case, a paid drafter of a memorial, a paid agent laying a petition before Government do not exercise or profess to exercise personal influence.)"),
        ("any public servant to do or to forbear to do any official act", "B", "... a public servant to do or forbear to do an official act?"),
        ("in the exercise of the official functions of such public servant to show favour or disfavour to any person", "B", "... a public servant to show favour or disfavour to anyone in the exercise of official functions?"),
        ("to render or attempt to render any service or disservice to any person with the Government, or with any Member of Parliament or the Cabinet, or with any public servant, as such", "B", "... a public servant to render or attempt to render any service or disservice to anyone with the Government, a Member of Parliament or the Cabinet, or a public servant?"),
        ("the accused is the taker", "B", "ss 162, 163: Is the accused the person who accepted or obtained the gratification?"),
        ("being a public servant, in respect of whom the offence is committed", "B", "s 164: Is the accused the public servant in respect of whom the s 162 or s 163 offence was committed?"),
        ("abets the offence", "B", "s 164: Did the accused abet that offence (s 107 - defined in pc-general-part; joined at integration)?"),
        ("the giver", "P", "The person from whom the gratification was accepted or obtained, as the charge names them"),
        ("the taker", "P", "For s 164: the person who took the gratification, as the charge names them"),
        ("the public servant", "P", "The public servant to be influenced, as the charge names them"),
        ("the gratification", "S", "The gratification, as it is to read in the charge"),
        TO_WIT,
    ]))
    A("")
    A(simple_pun("162", "3 years", 36))
    A("")
    INFLUENCED = """(    f's `any public servant to do or to forbear to do any official act`
         OR  f's `in the exercise of the official functions of such public servant to show favour or disfavour to any person`
         OR  f's `to render or attempt to render any service or disservice to any person with the Government, or with any Member of Parliament or the Cabinet, or with any public servant, as such` )"""
    INFL_EXPR = "f's `any public servant to do or to forbear to do any official act` OR f's `in the exercise of the official functions of such public servant to show favour or disfavour to any person` OR f's `to render or attempt to render any service or disservice to any person with the Government, or with any Member of Parliament or the Cabinet, or with any public servant, as such`"
    A(rule("takes a gratification to influence a public servant by corrupt means", GI,
           "Whether a gratification is taken as a motive or reward for inducing a public servant by corrupt or illegal means, within section 162 of the Penal Code 1871",
           f"""        "Whoever"
    AND {TAKE_LADDER}
    AND "from any person, for himself or for any other person,"
    AND f's `any gratification whatever`
    AND f's `as a motive or reward for inducing`
    AND f's `by corrupt or illegal means`
    AND {INFLUENCED}"""))
    A("")
    A(rule("offence under s 162", GI,
           "Whether the accused has committed an offence punishable under section 162 of the Penal Code 1871 (taking a gratification to influence a public servant by corrupt or illegal means)",
           """        f's `the accused is the taker`
    AND `takes a gratification to influence a public servant by corrupt means` f"""))
    A("")

    def m_infl(means_leaf, means_words, sec):
        return [("f's `the accused is the taker`", "the accused is the person who took the gratification"),
                (TAKE_EXPR, "accepts or obtains, or agrees to accept or attempts to obtain"),
                ("f's `any gratification whatever`", "any gratification"),
                ("f's `as a motive or reward for inducing`", "as a motive or reward for inducing a public servant"),
                (f"f's `{means_leaf}`", means_words),
                (INFL_EXPR, "to do or forbear an official act, to show favour or disfavour, or to render service or disservice"),
                ]

    def rec_infl(means):
        return """CONCAT "did """ + '", ' + take_verb() + """, " from ", `one person` (f's `the giver`), ", a gratification, namely ", f's `the gratification`, ", as a motive or reward for inducing, """ + means + """, ", `one person` (f's `the public servant`), ", a public servant, to do or forbear to do an official act or to show favour or disfavour in the exercise of official functions", `the to-wit clause` (f's `to wit`)"""
    A(charge("162", "taking a gratification in order, by corrupt or illegal means, to influence a public servant", "offence under s 162",
             rec_infl("by corrupt or illegal means"),
             m_infl("by corrupt or illegal means", "by corrupt or illegal means", "162") + [("`takes a gratification to influence a public servant by corrupt means` f", "the elements of section 162 taken together")],
             GI))
    A("")
    A(section("163", "Taking a gratification, for the exercise of personal influence with a public servant"))
    A("")
    A(simple_pun("163", "one year", 12))
    A("")
    A(rule("takes a gratification for personal influence with a public servant", GI,
           "Whether a gratification is taken as a motive or reward for inducing a public servant by the exercise of personal influence, within section 163 of the Penal Code 1871",
           f"""        "Whoever"
    AND {TAKE_LADDER}
    AND "from any person, for himself or for any other person,"
    AND f's `any gratification whatever`
    AND f's `as a motive or reward for inducing`
    AND f's `by the exercise of personal influence`
    AND {INFLUENCED}"""))
    A("")
    A(rule("offence under s 163", GI,
           "Whether the accused has committed an offence punishable under section 163 of the Penal Code 1871 (taking a gratification for the exercise of personal influence with a public servant)",
           """        f's `the accused is the taker`
    AND `takes a gratification for personal influence with a public servant` f"""))
    A("")
    A(charge("163", "taking a gratification for the exercise of personal influence with a public servant", "offence under s 163",
             rec_infl("by the exercise of personal influence"),
             m_infl("by the exercise of personal influence", "by the exercise of personal influence", "163") + [("`takes a gratification for personal influence with a public servant` f", "the elements of section 163 taken together")],
             GI))
    A("")
    A(section("164", "Punishment for abetment by public servant of the offences above defined"))
    A("")
    A(simple_pun("164", "3 years", 36))
    A("")
    A(rule("offence under s 164", GI,
           "Whether the accused, the public servant in respect of whom an offence under section 162 or 163 of the Penal Code 1871 is committed, abets it (section 164)",
           """        "Whoever,"
    AND f's `being a public servant, in respect of whom the offence is committed`
    AND "either of the offences defined in sections 162 and 163"
    AND (    `takes a gratification to influence a public servant by corrupt means` f
         OR  `takes a gratification for personal influence with a public servant` f )
    AND f's `abets the offence`"""))
    A("")
    A(charge("164", "abetment by a public servant of an offence under section 162 or 163", "offence under s 164",
             """CONCAT "being a public servant in respect of whom an offence under section ", (IF `takes a gratification to influence a public servant by corrupt means` f THEN "162" ELSE "163"), " of the Penal Code 1871 was committed by ", `one person` (f's `the taker`), ", did abet the said offence", `the to-wit clause` (f's `to wit`)""",
             [("f's `being a public servant, in respect of whom the offence is committed`", "being a public servant in respect of whom the offence is committed"),
              ("`takes a gratification to influence a public servant by corrupt means` f OR `takes a gratification for personal influence with a public servant` f", "an offence defined in section 162 or 163"),
              ("f's `abets the offence`", "abets the offence")],
             GI))
    A("")

    # 165
    VT = "Valuable Thing Facts"
    A(section("165", "Public servant obtaining any valuable thing, without consideration, from person concerned in any proceeding or business transacted by such public servant"))
    A("")
    A(facts(VT, "Penal Code 1871 s 165", [PS, THE_PS] + [(n, t, d.replace("the taker", "the accused")) for n, t, d in TAKE_FIELDS] + [
        ("any valuable thing", "B", "Was it a valuable thing (money, shares, a lease on favourable terms ...)?"),
        ("without consideration", "B", "Was it without consideration?"),
        ("for a consideration which he knows to be inadequate", "B", "Was it for a consideration the accused knew to be inadequate?"),
        ("from any person whom he knows to have been, or to be, or to be likely to be concerned in any proceedings or business transacted or about to be transacted by such public servant, or having any connection with the official functions of himself or of any public servant to whom he is subordinate", "B", "Was it from a person the accused knew to have been, to be, or to be likely to be concerned in proceedings or business transacted (or about to be) by the accused, or connected with the official functions of the accused or of a superior?"),
        ("from any person whom he knows to be interested in or related to the person so concerned", "B", "Was it from a person the accused knew to be interested in, or related to, such a person?"),
        ("the giver", "P", "The person from whom it was obtained, as the charge names them"),
        ("the valuable thing", "S", "The valuable thing, as it is to read in the charge - for example \"the lease of a house at $50 a month\""),
        TO_WIT,
    ]))
    A("")
    A(simple_pun("165", "2 years", 24))
    A("")
    A(rule("obtains a valuable thing from a person concerned in his business", VT,
           "Whether a public servant obtains a valuable thing without adequate consideration from a person concerned in business the public servant transacts, within section 165 of the Penal Code 1871",
           f"""        "Whoever, being a"
    AND f's `public servant`
    AND {TAKE_LADDER}
    AND "for himself or for any other person,"
    AND f's `any valuable thing`
    AND (    f's `without consideration`
         OR  f's `for a consideration which he knows to be inadequate` )
    AND (    f's `from any person whom he knows to have been, or to be, or to be likely to be concerned in any proceedings or business transacted or about to be transacted by such public servant, or having any connection with the official functions of himself or of any public servant to whom he is subordinate`
         OR  f's `from any person whom he knows to be interested in or related to the person so concerned` )"""))
    A("")
    A(rule("offence under s 165", VT,
           "Whether the accused has committed an offence punishable under section 165 of the Penal Code 1871 (public servant obtaining a valuable thing without consideration from a person concerned in business transacted by him)",
           """        "Whoever"
    ... `obtains a valuable thing from a person concerned in his business` f"""))
    A("")
    A(charge("165", "public servant obtaining a valuable thing, without consideration, from a person concerned in business transacted by him", "offence under s 165",
             """CONCAT "being a public servant, did """ + '", ' + take_verb() + """, " from ", `one person` (f's `the giver`), ", ", f's `the valuable thing`, ", ", (IF f's `without consideration` THEN "without consideration" ELSE "for a consideration which you knew to be inadequate"), ", the said ", f's `the giver`'s name, " being a person whom you knew to be concerned in proceedings or business transacted by you or connected with your official functions", `the to-wit clause` (f's `to wit`)""",
             [("f's `public servant`", "being a public servant"),
              (TAKE_EXPR, "accepts or obtains, or agrees to accept or attempts to obtain"),
              ("f's `any valuable thing`", "any valuable thing"),
              ("f's `without consideration` OR f's `for a consideration which he knows to be inadequate`", "without consideration, or for a consideration he knows to be inadequate"),
              ("f's `from any person whom he knows to have been, or to be, or to be likely to be concerned in any proceedings or business transacted or about to be transacted by such public servant, or having any connection with the official functions of himself or of any public servant to whom he is subordinate` OR f's `from any person whom he knows to be interested in or related to the person so concerned`", "from a person he knows to be concerned in his proceedings or business, or interested in or related to such a person"),
              ("`obtains a valuable thing from a person concerned in his business` f", "the elements of section 165 taken together")],
             VT))
    A("")

    # 166
    DL = "Disobeying Direction of Law Facts"
    A(section("166", "Public servant disobeying a direction of the law, with intent to cause injury to any person"))
    A("")
    A(facts(DL, "Penal Code 1871 s 166; s 44", [
        PS,
        ("knowingly", "B", "Did the accused act knowingly (s 26D)?"),
        ("disobeys any direction of the law as to the way in which he is to conduct himself as such public servant", "B", "Did the accused disobey a direction of the law as to how the accused was to conduct themselves as a public servant?"),
        ("intending to cause", "B", "Did the accused intend by the disobedience to cause injury to anyone?"),
        ("knowing it to be likely that he will, by such disobedience, cause", "B", "Did the accused know it was likely the disobedience would cause injury to anyone?"),
        ("injury to any person", "B", "Is the harm in question an injury (s 44) to a person?"),
        ("the direction", "S", "The direction of the law, as it is to read in the charge"),
        TO_WIT,
    ]))
    A("")
    A(simple_pun("166", "one year", 12))
    A("")
    A(rule("disobeys a direction of the law with intent to cause injury", DL,
           "Whether a public servant knowingly disobeys a direction of the law intending, or knowing it likely, to cause injury, within section 166 of the Penal Code 1871",
           """        "Whoever, being a"
    AND f's `public servant`
    AND f's knowingly
    AND f's `disobeys any direction of the law as to the way in which he is to conduct himself as such public servant`
    AND (    f's `intending to cause`
         OR  f's `knowing it to be likely that he will, by such disobedience, cause` )
    AND f's `injury to any person`"""))
    A("")
    A(rule("offence under s 166", DL,
           "Whether the accused has committed an offence punishable under section 166 of the Penal Code 1871 (public servant disobeying a direction of the law with intent to cause injury)",
           """        "Whoever"
    ... `disobeys a direction of the law with intent to cause injury` f"""))
    A("")
    A(charge("166", "public servant disobeying a direction of the law, with intent to cause injury", "offence under s 166",
             """CONCAT "being a public servant, did knowingly disobey a direction of the law as to the way in which you were to conduct yourself as such public servant, namely ", f's `the direction`, ", ", (IF f's `intending to cause` THEN "intending" ELSE "knowing it to be likely"), " thereby to cause injury to any person", `the to-wit clause` (f's `to wit`)""",
             [("f's `public servant`", "being a public servant"),
              ("f's knowingly", "knowingly"),
              ("f's `disobeys any direction of the law as to the way in which he is to conduct himself as such public servant`", "disobeys a direction of the law as to his conduct as a public servant"),
              ("f's `intending to cause` OR f's `knowing it to be likely that he will, by such disobedience, cause`", "intending, or knowing it to be likely, to cause"),
              ("f's `injury to any person`", "injury to any person")],
             DL))
    A("")

    # 167
    ID = "Incorrect Document Facts"
    A(section("167", "Public servant framing an incorrect document or electronic record with intent to cause injury"))
    A("")
    A(facts(ID, "Penal Code 1871 s 167; ss 29, 29B, 44", [
        PS,
        ("charged, as such public servant, with the preparation or translation of any document or electronic record", "B", "Was the accused, as a public servant, charged with preparing or translating a document (s 29) or electronic record (s 29B)?"),
        ("frames or translates that document or electronic record", "B", "Did the accused frame or translate it?"),
        ("in a manner which he knows or believes to be incorrect", "B", "... in a manner the accused knew or believed to be incorrect?"),
        ("intending thereby to cause", "B", "Did the accused intend by it to cause injury to anyone?"),
        ("knowing it to be likely that he may thereby cause", "B", "Did the accused know it was likely to cause injury to anyone?"),
        ("injury to any person", "B", "Is the harm in question an injury (s 44) to a person?"),
        ("the document", "S", "The document or electronic record, as it is to read in the charge"),
        TO_WIT,
    ]))
    A("")
    A(simple_pun("167", "3 years", 36))
    A("")
    A(rule("frames an incorrect document with intent to cause injury", ID,
           "Whether a public servant charged with preparing or translating a document frames it incorrectly with intent, or knowing it likely, to cause injury, within section 167 of the Penal Code 1871",
           """        "Whoever, being a"
    AND f's `public servant`
    AND f's `charged, as such public servant, with the preparation or translation of any document or electronic record`
    AND f's `frames or translates that document or electronic record`
    AND f's `in a manner which he knows or believes to be incorrect`
    AND (    f's `intending thereby to cause`
         OR  f's `knowing it to be likely that he may thereby cause` )
    AND f's `injury to any person`"""))
    A("")
    A(rule("offence under s 167", ID,
           "Whether the accused has committed an offence punishable under section 167 of the Penal Code 1871 (public servant framing an incorrect document with intent to cause injury)",
           """        "Whoever"
    ... `frames an incorrect document with intent to cause injury` f"""))
    A("")
    A(charge("167", "public servant framing an incorrect document or electronic record with intent to cause injury", "offence under s 167",
             """CONCAT "being a public servant charged, as such public servant, with the preparation of ", f's `the document`, ", did frame the same in a manner which you knew or believed to be incorrect, ", (IF f's `intending thereby to cause` THEN "intending" ELSE "knowing it to be likely"), " thereby to cause injury to any person", `the to-wit clause` (f's `to wit`)""",
             [("f's `public servant`", "being a public servant"),
              ("f's `charged, as such public servant, with the preparation or translation of any document or electronic record`", "charged, as such, with the preparation or translation of the document"),
              ("f's `frames or translates that document or electronic record`", "frames or translates it"),
              ("f's `in a manner which he knows or believes to be incorrect`", "in a manner he knows or believes to be incorrect"),
              ("f's `intending thereby to cause` OR f's `knowing it to be likely that he may thereby cause`", "intending, or knowing it to be likely, to cause"),
              ("f's `injury to any person`", "injury to any person")],
             ID))
    A("")

    # 168, 169
    TR = "Public Servant Trading Facts"
    A(section("168", "Public servant unlawfully engaging in trade"))
    A("")
    A(facts(TR, "Penal Code 1871 ss 168, 169", [
        PS,
        ("legally bound as such public servant not to engage in trade", "B", "s 168: Was the accused, as a public servant, legally bound not to engage in trade?"),
        ("engages in trade", "B", "s 168: Did the accused engage in trade?"),
        ("legally bound as such public servant not to purchase or bid for certain property", "B", "s 169: Was the accused, as a public servant, legally bound not to purchase or bid for certain property?"),
        ("purchases or bids for that property", "B", "s 169: Did the accused purchase or bid for that property - in the accused's own name or another's, or jointly or in shares with others?"),
        ("the property is purchased", "B", "s 169: Was the property in fact purchased? (It is then confiscated - part of the punishment, not an element.)"),
        ("the trade or property", "S", "The trade, or the property, as it is to read in the charge"),
        TO_WIT,
    ]))
    A("")
    A(simple_pun("168", "one year", 12))
    A("")
    A(rule("offence under s 168", TR,
           "Whether the accused has committed an offence punishable under section 168 of the Penal Code 1871 (public servant unlawfully engaging in trade)",
           """        "Whoever, being a"
    AND f's `public servant`
    AND f's `legally bound as such public servant not to engage in trade`
    AND f's `engages in trade`""",
           comment="s 168 defines and punishes in one breath with no verb of its own; the offence\nladder is the defining predicate (so `definitionFns` is empty)."))
    A("")
    A(charge("168", "public servant unlawfully engaging in trade", "offence under s 168",
             """CONCAT "being a public servant legally bound as such not to engage in trade, did engage in trade, namely ", f's `the trade or property`, `the to-wit clause` (f's `to wit`)""",
             [("f's `public servant`", "being a public servant"),
              ("f's `legally bound as such public servant not to engage in trade`", "legally bound as such not to engage in trade"),
              ("f's `engages in trade`", "engages in trade")],
             TR))
    A("")
    A(section("169", "Public servant unlawfully buying or bidding for property"))
    A("")
    A(pun("169", "imprisonment for a term which may extend to 2 years, or with fine, or with both; and the property, if purchased, shall be confiscated",
          imp="or", mx=24, fine="or", both=True, forf="sh"))
    A("")
    A(rule("offence under s 169", TR,
           "Whether the accused has committed an offence punishable under section 169 of the Penal Code 1871 (public servant unlawfully buying or bidding for property)",
           """        "Whoever, being a"
    AND f's `public servant`
    AND f's `legally bound as such public servant not to purchase or bid for certain property`
    AND f's `purchases or bids for that property`""",
           comment="FORK SP-169: \"the property, if purchased, shall be confiscated\" is recorded as\nforfeiture `shall be punished with`; the record cannot say \"if purchased\", the words do."))
    A("")
    A(charge("169", "public servant unlawfully buying or bidding for property", "offence under s 169",
             """CONCAT "being a public servant legally bound as such not to purchase or bid for certain property, did ", (IF f's `the property is purchased` THEN "purchase" ELSE "bid for"), " that property, namely ", f's `the trade or property`, `the to-wit clause` (f's `to wit`)""",
             [("f's `public servant`", "being a public servant"),
              ("f's `legally bound as such public servant not to purchase or bid for certain property`", "legally bound as such not to purchase or bid for certain property"),
              ("f's `purchases or bids for that property`", "purchases or bids for that property")],
             TR))
    A("")

    # 170
    PE = "Personation of Public Servant Facts"
    A(section("170", "Personating a public servant"))
    A("")
    A(facts(PE, "Penal Code 1871 s 170", [
        ("pretends to hold any particular office as a public servant", "B", "Did the accused pretend to hold a particular office as a public servant (for example, a police officer)?"),
        ("knowing that he does not hold such office", "B", "Did the accused know they did not hold that office?"),
        ("falsely personates any other person holding such office", "B", "Did the accused falsely personate another person who holds such an office?"),
        ("in such assumed character", "B", "Was what the accused did done in that assumed character?"),
        ("does or attempts to do any act under colour of such office", "B", "Did the accused do, or attempt to do, an act under colour of that office?"),
        ("the office", "S", "The office pretended, as it is to read in the charge - for example \"a police officer\""),
        TO_WIT,
    ]))
    A("")
    A(simple_pun("170", "2 years", 24))
    A("")
    A(rule("personates a public servant", PE,
           "Whether the accused pretends to hold, or personates the holder of, a public office and acts under colour of it, within section 170 of the Penal Code 1871",
           """        "Whoever"
    AND (    (    f's `pretends to hold any particular office as a public servant`
              AND f's `knowing that he does not hold such office` )
         OR  f's `falsely personates any other person holding such office` )
    AND "and"
    AND f's `in such assumed character`
    AND f's `does or attempts to do any act under colour of such office`"""))
    A("")
    A(rule("offence under s 170", PE,
           "Whether the accused has committed an offence punishable under section 170 of the Penal Code 1871 (personating a public servant)",
           """        "Whoever"
    ... `personates a public servant` f"""))
    A("")
    A(charge("170", "personating a public servant", "offence under s 170",
             """CONCAT (IF f's `falsely personates any other person holding such office` THEN CONCAT "did falsely personate a person holding the office of ", f's `the office` ELSE CONCAT "did pretend to hold the office of ", f's `the office`, ", a public servant, knowing that you did not hold such office"), ", and in such assumed character did an act under colour of such office", `the to-wit clause` (f's `to wit`)""",
             [("(f's `pretends to hold any particular office as a public servant` AND f's `knowing that he does not hold such office`) OR f's `falsely personates any other person holding such office`", "pretends to hold a particular office as a public servant, knowing he does not hold it, or falsely personates a person holding it"),
              ("f's `in such assumed character`", "in such assumed character"),
              ("f's `does or attempts to do any act under colour of such office`", "does or attempts to do any act under colour of such office"),
              ("`personates a public servant` f", "the elements of section 170 taken together")],
             PE))
    A("")

    # 171
    GA = "Public Servant Garb Facts"
    A(section("171", "Wearing garb or carrying token used by public servant, with fraudulent intent"))
    A("")
    A(facts(GA, "Penal Code 1871 s 171", [
        ("not belonging to a certain class of public servants", "B", "Is the accused NOT a member of the class of public servants whose garb or token it is?"),
        ("wears any garb or carries any token resembling any garb or token used by that class of public servants", "B", "Did the accused wear a garb, or carry a token, resembling one used by that class (for example, a police uniform or warrant card)?"),
        ("with the intention that it may be believed that he belongs to that class of public servants", "B", "Did the accused intend it to be believed that they belonged to that class?"),
        ("with the knowledge that it is likely to be believed that he belongs to that class of public servants", "B", "Did the accused know it was likely to be believed that they belonged to that class?"),
        ("the class", "S", "The class of public servants, as it is to read in the charge - for example \"police officers\""),
        ("the garb or token", "S", "The garb or token, as it is to read in the charge - for example \"a police uniform\""),
        TO_WIT,
    ]))
    A("")
    A(simple_pun("171", "6 months", 6, "fine which may extend to $1,000", 1000))
    A("")
    A(rule("wears the garb of a public servant", GA,
           "Whether the accused, not belonging to a class of public servants, wears its garb or carries its token intending or knowing it likely to be believed that the accused belongs to it, within section 171 of the Penal Code 1871",
           """        "Whoever,"
    AND f's `not belonging to a certain class of public servants`
    AND f's `wears any garb or carries any token resembling any garb or token used by that class of public servants`
    AND (    f's `with the intention that it may be believed that he belongs to that class of public servants`
         OR  f's `with the knowledge that it is likely to be believed that he belongs to that class of public servants` )"""))
    A("")
    A(rule("offence under s 171", GA,
           "Whether the accused has committed an offence punishable under section 171 of the Penal Code 1871 (wearing the garb or carrying the token of a public servant with fraudulent intent)",
           """        "Whoever"
    ... `wears the garb of a public servant` f"""))
    A("")
    A(charge("171", "wearing the garb or carrying the token of a public servant with fraudulent intent", "offence under s 171",
             """CONCAT "not belonging to the class of public servants, namely ", f's `the class`, ", did wear or carry ", f's `the garb or token`, ", resembling a garb or token used by that class, ", (IF f's `with the intention that it may be believed that he belongs to that class of public servants` THEN "with the intention that it might be believed" ELSE "with the knowledge that it was likely to be believed"), " that you belonged to that class of public servants", `the to-wit clause` (f's `to wit`)""",
             [("f's `not belonging to a certain class of public servants`", "not belonging to a certain class of public servants"),
              ("f's `wears any garb or carries any token resembling any garb or token used by that class of public servants`", "wears a garb or carries a token resembling one used by that class"),
              ("f's `with the intention that it may be believed that he belongs to that class of public servants` OR f's `with the knowledge that it is likely to be believed that he belongs to that class of public servants`", "with the intention, or knowledge of the likelihood, that it be believed he belongs to that class"),
              ("`wears the garb of a public servant` f", "the elements of section 171 taken together")],
             GA))
    A("")
    return "\n".join(out)


def tests():
    T = []
