    A(fixture("163 illus: the advocate's fee", "Gratification to Influence Facts",
              ["accepts", "any gratification whatever", "as a motive or reward for inducing",
               "any public servant to do or to forbear to do any official act", "the accused is the taker"],
              comment="s 163 illus: an advocate who receives a fee for arguing a case before a judge is not within s 163,\n\"inasmuch as they do not exercise or profess to exercise personal influence\"."))
    A("-- s 163 illus")
